using NUnit.Framework;using UnityEditor;using UnityEditor.AddressableAssets;using UnityEngine;using UnityEngine.UI;using Rootborn.UI.Modern;using Rootborn.Game.Common;using Rootborn.Game.Localization;using Rootborn.Game.Player;using System.Linq;namespace Rootborn.Tests.EditMode.UI.Modern{public sealed class UrbanInventoryDetailCloseTests{
[Test]public void CloseGlyphUsesReviewedPixelGeometryAndSavedThemeDependency(){const string path="Assets/Art/UI/UrbanMolding/inventory_close.png";var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(s,Is.Not.Null);Assert.That(s.rect.size,Is.EqualTo(new Vector2(32,32)));Assert.That(s.pivot,Is.EqualTo(new Vector2(16,16)));Assert.That(s.pixelsPerUnit,Is.EqualTo(16));var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));Assert.That(AddressableAssetSettingsDefaultObject.Settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path)).address,Is.EqualTo("sprites/ui/urban-life/inventory-close"));Assert.That(AssetDatabase.LoadAssetAtPath<UrbanUiThemeDefinition>("Assets/Data/UI/UrbanMoldingTheme.asset").GetIcon("close"),Is.SameAs(s));}
[TestCase("ko","닫기",false)][TestCase("en","Close",false)][TestCase("ko","닫기",true)][TestCase("en","Close",true)]public void DetailCloseHasLocalizedNonBlockingLabelAndClosesOnlyPopupWithoutChangingItems(string lang,string expected,bool missingCatalog){string language=GameText.Language;var root=new GameObject("Inventory",typeof(RectTransform));var player=new GameObject("CloseFixture",typeof(PlayerInventory));var empty=missingCatalog?ScriptableObject.CreateInstance<GameDataRegistry>():null;var item=AssetDatabase.LoadAssetAtPath<ItemDefinition>("Assets/Data/Items/Item_Allowance.asset");try{GameText.Language=lang;GameDataRegistryProvider.SetOverrideForTests(missingCatalog?empty:AssetDatabase.LoadAssetAtPath<GameDataRegistry>("Assets/Data/Registry/GameDataRegistry.asset"));var inventory=player.GetComponent<PlayerInventory>();inventory.Inventory.Add(item,12);var panel=root.AddComponent<ModernUiInventoryPanel>();panel.Bind(inventory);panel.Show();root.GetComponentsInChildren<ScrollRect>().Single().content.GetChild(0).GetComponent<Button>().onClick.Invoke();var popup=root.transform.Find("ItemDetailPopup");var button=popup.Find("ActionButton");var label=button.Find("Label");Assert.That(label,Is.Not.Null,"Existing blank button needs a visible Close label");Assert.That(label.GetComponent<Text>().text,Is.EqualTo(expected));Assert.That(label.GetComponent<Text>().raycastTarget,Is.False);Assert.That(((RectTransform)button).sizeDelta,Is.EqualTo(new Vector2(192,64)));var icon=button.Find("Icon");Assert.That(icon,Is.Not.Null);Assert.That(icon.GetComponent<UrbanUiIcon>(),Is.Not.Null);Assert.That(icon.GetComponent<Image>().raycastTarget,Is.False);button.GetComponent<Button>().onClick.Invoke();Assert.That(root.transform.Find("ItemDetailPopup"),Is.Null);Assert.That(panel.IsVisible,Is.True);Assert.That(inventory.Inventory.CountOf(item),Is.EqualTo(12));Assert.That(root.GetComponentsInChildren<ScrollRect>().Single().content.childCount,Is.EqualTo(Rootborn.Game.Common.Inventory.MaxSlots));}finally{Object.DestroyImmediate(root);Object.DestroyImmediate(player);if(empty!=null)Object.DestroyImmediate(empty);GameText.Language=language;GameDataRegistryProvider.ClearOverrideForTests();GameDataRegistryProvider.ResetCacheForTests();}}
}}
